#!/usr/bin/env node
// PreToolUse hook (Write|Edit): blocks direct edits to files that are
// regenerated by tooling rather than hand-written, so a well-meaning edit
// doesn't get silently clobbered by the next `npm run build`/`npm run dev`.
"use strict";

let input = "";
process.stdin.on("data", (chunk) => {
  input += chunk;
});
process.stdin.on("end", () => {
  let payload;
  try {
    payload = JSON.parse(input);
  } catch {
    return;
  }

  const rawFile = (payload.tool_input && payload.tool_input.file_path) || "";
  const file = rawFile.replace(/\\/g, "/");

  let reason = null;
  if (/(^|\/)next-env\.d\.ts$/.test(file)) {
    reason =
      "next-env.d.ts is regenerated by Next.js on every dev/build run (its own header says " +
      "\"This file should not be edited\"). Change next.config.mjs or tsconfig.json instead.";
  } else if (/(^|\/)\.next\//.test(file)) {
    reason = ".next/ is Next.js build output, regenerated by npm run dev/build — never hand-edited.";
  } else if (/(^|\/)out\//.test(file)) {
    reason = "out/ is the static export output, regenerated by npm run build — never hand-edited.";
  }

  if (reason) {
    process.stdout.write(
      JSON.stringify({
        hookSpecificOutput: {
          hookEventName: "PreToolUse",
          permissionDecision: "deny",
          permissionDecisionReason: reason,
        },
      })
    );
  }
});
